measurement_driver:
// Diagnostic runner: execute the maintained benchmark bodies once per process.
// Their module-level validation provides one warm collection at each size.
const cases: Deno.BenchDefinition[] = [];
Deno.bench = ((definition: Deno.BenchDefinition) => {
  cases.push(definition);
}) as typeof Deno.bench;
await import("file:///Users/berni/.codex/worktrees/e181/labs/packages/runner/test/cfc-consumed-source-dedup.bench.ts");
const results = [];
for (const definition of cases) {
  let start = NaN;
  let elapsed = NaN;
  const context = {
    name: definition.name,
    origin: import.meta.url,
    start: () => { start = performance.now(); },
    end: () => { elapsed = performance.now() - start; },
  } satisfies Deno.BenchContext;
  await definition.fn(context);
  if (!Number.isFinite(elapsed)) throw new Error("Missing explicit timer");
  results.push({ name: definition.name, ms: elapsed });
}
console.log(JSON.stringify({ runtime: Deno.version, results }));
